using Parrot.Store;

namespace Parrot.Core.Tests;

internal sealed class ImageInspectionTests
{
    private const string Png = "89504E470D0A1A0A0000000D49484452000000030000000208020000001216F14D0000001049444154789C63FCCF00054C3006030013290103F0D807840000000049454E44AE426082";
    private const string AnimatedPng = "";
    private const string AnimatedGif = "47494638376103000200810000FF00000000000000000000002C00000000030002000008060001081C18100021F90401000001002C0000000003000200810000FF00000000000000000008060001081C1810003B";
    private const string Jpeg = "";
    private const string ProgressiveJpeg = "";
    private const string LossyWebp = "524946463800000057454250565038202C0000009001009D012A0300020002C04C25A00274BA00039800FEEE431FEE6C738B7057FF6D0FFF5A1FFEB43FE94000";
    private const string LosslessWebp = "524946461C000000574542505650384C0F0000002F024000000710FD8FFE0722A2FF0100";
    private const string AnimatedWebp = "524946468400000057454250565038580A00000002000000020000010000414E494D06000000000000000000414E4D4628000000000000000000020000010000000000025650384C0F0000002F024000000710FD8FFE0722A2FF0100414E4D4628000000000000000000020000010000000000005650384C0F0000002F024000000710D1FFFE0722A2FF0100";

    [Test]
    [Arguments(Png, "image/png", 1)]
    [Arguments(AnimatedPng, "image/png", 2)]
    [Arguments(AnimatedGif, "image/gif", 2)]
    [Arguments(Jpeg, "image/jpeg", 1)]
    [Arguments(ProgressiveJpeg, "image/jpeg", 1)]
    [Arguments(LossyWebp, "image/webp", 1)]
    [Arguments(LosslessWebp, "image/webp", 1)]
    [Arguments(AnimatedWebp, "image/webp", 2)]
    public async Task Inspects_format_dimensions_and_frames(string hex, string mediaType, int frameCount)
    {
        var data = Convert.FromHexString(hex);

        _ = await Assert.That(ImageInspection.DetectMediaType(data.AsSpan(0, ImageInspection.HeaderLength))).IsEqualTo(mediaType);
        _ = await Assert.That(ImageInspection.Inspect(data)).IsEqualTo(new ImageInspection(mediaType, 3, 2, frameCount));
    }

    [Test]
    [Arguments(Png)]
    [Arguments(AnimatedPng)]
    [Arguments(AnimatedGif)]
    [Arguments(Jpeg)]
    [Arguments(ProgressiveJpeg)]
    [Arguments(LossyWebp)]
    [Arguments(LosslessWebp)]
    [Arguments(AnimatedWebp)]
    [Arguments("000102000102000102000102")]
    public async Task Rejects_truncated_and_unknown_images(string hex)
    {
        var data = Convert.FromHexString(hex)[..^1];

        _ = await Assert.That(() => ImageInspection.Inspect(data)).Throws<InvalidDataException>();
    }
}
